    private record Scene(NativeCanopyRenderSnapshot visual,double progress,NativeCanopyRenderer.Draw draw,NativeCanopyRenderer.Draw wrong,double[] bounds){}
    private static NativeCanopyRenderer.Bake bake,wrongBake;private static Scene[] scenes;private static int frames,generation,checks;private static int[][] background;private static boolean done;
    private static boolean enabled(){return "true".equals(System.getenv("VANDOR_CANOPY_RENDER_CHECK"));}
    private static void need(boolean yes,String message){checks++;if(!yes)throw new AssertionError("Canopy GPU "+message);}
    private static NativeCanopyRenderSnapshot visual(String kind,int shade,int tint,int material,int layout,int mount,int motion,int hinge,int depth,int scale){CompoundTag tag=new CompoundTag();tag.putInt("CanopyShade",shade);tag.putInt("CanopyTint",tint);tag.putInt("CanopyMaterial",material);tag.putInt("CanopyTextureLayout",layout);tag.putBoolean("CanopyTileMaterial",layout==1);tag.putInt("CanopyMount",mount);tag.putInt("CanopyMotion",motion);tag.putInt("CanopyHinge",hinge);tag.putInt("CanopyDepth",depth);tag.putInt("CanopyScale",scale);tag.putBoolean("CanopyOpenable",true);return new NativeCanopyRenderSnapshot(kind,2,NativeCanopyModels.builtin().dimensions(kind).width(),0,0,kind.contains("front_canopy")||kind.startsWith("space_visor"),NativeCanopySettings.read(tag));}
    private static Scene scene(NativeCanopyRenderSnapshot visual,double pose){var draw=bake.draw(visual,pose);return new Scene(visual,pose,draw,wrongBake.draw(visual,pose),draw.bounds());}
    private static final class Collector implements VertexConsumer {final List<int[]> vertices=new ArrayList<>();int[] last;public VertexConsumer addVertex(float x,float y,float z){last=new int[8];last[0]=Float.floatToRawIntBits(x);last[1]=Float.floatToRawIntBits(y);last[2]=Float.floatToRawIntBits(z);vertices.add(last);return this;}public VertexConsumer setColor(int r,int g,int b,int a){last[3]=r|g<<8|b<<16|a<<24;return this;}public VertexConsumer setUv(float u,float v){last[4]=Float.floatToRawIntBits(u);last[5]=Float.floatToRawIntBits(v);return this;}public VertexConsumer setUv1(int u,int v){return this;}public VertexConsumer setUv2(int u,int v){last[6]=u|v<<16;return this;}public VertexConsumer setNormal(float x,float y,float z){last[7]=((byte)(x*127)&255)|(((byte)(y*127)&255)<<8)|(((byte)(z*127)&255)<<16);return this;}}
    private static void terrainChecks(){
        long words=0;int profiles=0;var pose=new PoseStack();var random=net.minecraft.util.RandomSource.create(0);var model=new NativeCanopyTerrainModel(Minecraft.getInstance().getModelManager().getMissingModel(),bake);NativeCanopyRenderSnapshot last=null;net.neoforged.neoforge.client.model.data.ModelData lastData=null;
        for(int facing=2;facing<=5;facing++)for(int mask=0;mask<16;mask++)for(int roof=0;roof<16;roof++){if((roof&~mask)!=0)continue;var base=visual("regular_canopy_glass",1,1,-1,0,0,0,2,16,71);var visual=new NativeCanopyRenderSnapshot(base.kind(),facing,1,mask,roof,false,base.settings());var data=net.neoforged.neoforge.client.model.data.ModelData.builder().with(NativeCanopyEntity.TERRAIN,visual).build();var draw=bake.draw(visual,0);var capture=new Collector();draw.emit(pose.last(),ignored->capture,0,OverlayTexture.NO_OVERLAY,true,true);var quads=model.getQuads(null,null,random,data,null);need(quads.size()*4==capture.vertices.size(),"fixed terrain quad count");for(int q=0;q<quads.size();q++){var quad=quads.get(q);need(!quad.isShade()&&!quad.hasAmbientOcclusion()&&quad.getTintIndex()==-1,"fixed Source diffuse/AO/tint policy");need(quad.getSprite()!=null,"actual per-face atlas sprite");for(int v=0;v<4;v++)for(int word=0;word<8;word++){need(quad.getVertices()[v*8+word]==capture.vertices.get(q*4+v)[word],"fixed terrain emitted word "+word);words++;}}need(model.getQuads(null,net.minecraft.core.Direction.NORTH,random,data,null).isEmpty(),"unculled fixed faces only");need(model.getQuads(null,null,random,net.neoforged.neoforge.client.model.data.ModelData.EMPTY,null).isEmpty(),"no duplicate helper/default geometry");need(model.getQuads(null,null,random,data,net.minecraft.client.renderer.RenderType.solid()).size()+model.getQuads(null,null,random,data,net.minecraft.client.renderer.RenderType.translucent()).size()==quads.size(),"independent fixed body/pane layers");last=visual;lastData=data;profiles++;}
        var retainedData=lastData;var retainedQuads=model.getQuads(null,null,random,retainedData,null);need(java.util.concurrent.CompletableFuture.supplyAsync(()->model.getQuads(null,null,random,retainedData,null)).join()==retainedQuads,"world-free worker retains immutable fixed quads");var bean=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();bean.setThreadAllocatedMemoryEnabled(true);long thread=Thread.currentThread().threadId();for(int i=0;i<10000;i++)model.getQuads(null,null,random,retainedData,null);long before=bean.getThreadAllocatedBytes(thread);for(int i=0;i<10000;i++)model.getQuads(null,null,random,retainedData,null);need(bean.getThreadAllocatedBytes(thread)-before==0,"warmed fixed chunk queries allocate zero bytes");System.out.println("[vandorlabs][canopy-render] terrain profiles="+profiles+" words="+words+" warmedQueries10000 allocated0");
    }
    private static void prepare()throws Exception {
        Minecraft mc=Minecraft.getInstance();var wall=NativePanelPlaybackRenderer.currentBake();need(wall!=null,"shared completed wall bake");java.util.function.Function<Material,TextureAtlasSprite> textures=m->mc.getTextureAtlas(TextureAtlas.LOCATION_BLOCKS).apply(m.texture());
        bake=new NativeCanopyRenderer.Bake(wall,textures);wrongBake=new NativeCanopyRenderer.Bake(wall,m->wall.surfaces.get(64).sprite());
        for(var texture:NativeCanopyArtwork.textures()){var id=ResourceLocation.parse(texture.id());var sprite=textures.apply(new Material(TextureAtlas.LOCATION_BLOCKS,id));need(sprite.contents().name().equals(id)&&sprite.contents().width()==texture.width()&&sprite.contents().height()==texture.height(),"actual authored sheet "+id);try(var in=mc.getResourceManager().getResource(id.withPrefix("textures/").withSuffix(".png")).orElseThrow().open()){String hash=java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(in.readAllBytes()));need(hash.equals(texture.sha256()),"unchanged original artwork "+id);}if(texture.id().endsWith("_glass")){need(sprite.contents().byMipLevel.length>=3,"actual glass mip2");boolean visible=false;var image=sprite.contents().byMipLevel[2];for(int y=0;y<image.getHeight();y++)for(int x=0;x<image.getWidth();x++)visible|=(image.getPixelRGBA(x,y)>>>24)>0;need(visible,"low-alpha sheet survives mip2");}}
        terrainChecks();scenes=new Scene[]{scene(visual("regular_canopy_glass",1,1,-1,0,0,0,2,16,71),0),scene(visual("angled_front_1x1",2,2,-1,0,0,0,2,16,71),0),scene(visual("angled_front_1x2",0,1,-1,0,1,0,2,16,71),0),scene(visual("canopy",1,2,-1,0,0,0,2,16,71),0),scene(visual("canopy",4,2,-1,0,0,0,2,16,71),.5),scene(visual("long_canopy",2,1,-1,0,0,1,2,16,71),.5),scene(visual("front_canopy_glass",0,1,-1,0,2,0,0,24,90),.5),scene(visual("large_front_canopy_glass",0,1,64,1,3,1,1,80,100),.5),scene(visual("space_visor_2x1",2,1,-1,0,0,0,2,16,71),0),scene(visual("space_visor_3x1",14,3,-1,0,0,0,2,16,71),0),scene(visual("space_visor_5x1",0,1,64,1,0,0,2,16,71),0),scene(visual("space_visor_5x1_double_height",1,2,-1,0,0,0,2,16,71),0)};
        need(scenes.length==12,"11 authored families plus moving pose");for(var scene:scenes)need(scene.draw.bodyVertices()>0,"authored housing vertices");
    }
    @SubscribeEvent public static void draw(ScreenEvent.Render.Post event)throws Exception {
        if(done||!enabled()||!(event.getScreen() instanceof net.minecraft.client.gui.screens.TitleScreen))return;var mc=Minecraft.getInstance();if(mc.getOverlay()!=null)return;if(bake==null)prepare();var gui=event.getGuiGraphics();gui.flush();com.mojang.blaze3d.systems.RenderSystem.clear(org.lwjgl.opengl.GL11.GL_DEPTH_BUFFER_BIT,Minecraft.ON_OSX);gui.fill(0,0,mc.getWindow().getGuiScaledWidth(),mc.getWindow().getGuiScaledHeight(),0xff202830);gui.flush();var buffers=mc.renderBuffers().bufferSource();
        for(int i=0;i<scenes.length;i++){var scene=scenes[i];int px=10+i%4*155,py=8+i/4*112;gui.enableScissor(px,py,px+150,py+106);var pose=gui.pose();pose.pushPose();try{double[] b=scene.bounds;double span=Math.max(b[3]-b[0],Math.max(b[4]-b[1],b[5]-b[2])),scale=72/Math.max(1,span);pose.translate(px+75,py+53,350);pose.scale((float)scale,(float)-scale,(float)scale);pose.mulPose(Axis.XP.rotationDegrees(20));pose.mulPose(Axis.YP.rotationDegrees(-30));pose.translate(-(b[0]+b[3])/2,-(b[1]+b[4])/2,-(b[2]+b[5])/2);boolean negative=frames<5;var draw=negative&&i>=8?scene.wrong:scene.draw;draw.emit(pose.last(),buffers,0xF000F0,OverlayTexture.NO_OVERLAY,!negative||i%2!=0,!negative||i%2==0);buffers.endBatch();}finally{pose.popPose();gui.disableScissor();}}
        frames++;
    }
    private static void measure(){var meter=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();meter.setThreadAllocatedMemoryEnabled(true);long thread=Thread.currentThread().threadId();for(int i=0;i<4;i++)meter.getThreadAllocatedBytes(thread);int vertices=0;for(var scene:scenes)vertices+=scene.draw.bodyVertices()+scene.draw.paneVertices();int rounds=Math.max(1,Math.min(64,300000/vertices));var pose=new PoseStack();
        try(var storage=new ByteBufferBuilder(16*1024*1024)){for(int pass=0;pass<8;pass++){var warm=new BufferBuilder(storage,VertexFormat.Mode.QUADS,DefaultVertexFormat.BLOCK);MultiBufferSource source=ignored->warm;for(int i=0;i<rounds;i++)for(var scene:scenes)bake.draw(scene.visual,scene.progress).emit(pose.last(),source,0xF000F0,OverlayTexture.NO_OVERLAY,true,true);warm.buildOrThrow().close();storage.clear();}
            var target=new BufferBuilder(storage,VertexFormat.Mode.QUADS,DefaultVertexFormat.BLOCK);MultiBufferSource source=ignored->target;long builds=bake.builds(),before=meter.getThreadAllocatedBytes(thread);for(int i=0;i<rounds;i++)for(var scene:scenes)bake.draw(scene.visual,scene.progress).emit(pose.last(),source,0xF000F0,OverlayTexture.NO_OVERLAY,true,true);long allocated=meter.getThreadAllocatedBytes(thread)-before;try(var mesh=target.buildOrThrow()){need(allocated==0&&bake.builds()==builds&&mesh.drawState().vertexCount()==vertices*rounds,"actual multi-snapshot buffer batch allocation="+allocated);System.out.println("[vandorlabs][canopy-render] buffer COST snapshots12 draws="+(rounds*12)+" vertices="+mesh.drawState().vertexCount()+" allocated="+allocated+" newMeshes="+(bake.builds()-builds));}}
    }
    @SubscribeEvent public static void frame(RenderFrameEvent.Post event)throws Exception {
        if(done||!enabled()||(frames!=5&&frames!=25))return;if(frames==25)done=true;var mc=Minecraft.getInstance();try(var image=Screenshot.takeScreenshot(mc.getMainRenderTarget())){int scale=(int)mc.getWindow().getGuiScale(),width=150*scale,height=106*scale;if(frames==5){background=new int[12][width*height];for(int i=0;i<12;i++){int x0=(10+i%4*155)*scale,y0=(8+i/4*112)*scale;for(int y=0;y<height;y++)for(int x=0;x<width;x++)background[i][y*width+x]=image.getPixelRGBA(x0+x,y0+y);}measure();return;}int total=0;for(int i=0;i<12;i++){int x0=(10+i%4*155)*scale,y0=(8+i/4*112)*scale,ink=0,changed=0;for(int y=0;y<height;y++)for(int x=0;x<width;x++){int pixel=image.getPixelRGBA(x0+x,y0+y);if((pixel&0xffffff)!=0x302820)ink++;if(pixel!=background[i][y*width+x])changed++;}need(ink>40,"visible scene="+i+" pixels="+ink);need(changed>20,"independent housing/pane/artwork negative="+i+" changed="+changed);total+=changed;}var target=mc.gameDirectory.toPath().resolve("screenshots/canopy-native-"+generation+".png");java.nio.file.Files.createDirectories(target.getParent());image.writeToFile(target);need(bake.retainedBytes()<=8*1024*1024,"combined mesh/binding byte bound");System.out.println("[vandorlabs][canopy-render] generation="+generation+" changedPixels="+total+" retainedBytes="+bake.retainedBytes());}
        bake.clear();wrongBake.clear();need(bake.retainedBytes()==0&&wrongBake.retainedBytes()==0,"cache retirement");if(generation++==0){bake=null;wrongBake=null;frames=0;done=false;mc.reloadResourcePacks();return;}done=true;System.out.println("[vandorlabs][canopy-render] title PASS checks="+checks+" scenes12/all11families/artwork/opacity/motion/mount/consumer/reload; inactive software only");mc.stop();
    }
